def histogram(test):
    # Initialize an empty dictionary to store letter counts
    count_dict = {}

    # Split the input string into a list of letters and iterate over each letter
    for char in test.split():
        if char in count_dict:
            # If the character is already present, increment its count by 1
            count_dict[char] += 1
        else:
            # Otherwise add it to the dictionary with a count of 1
            count_dict[char] = 1

    # Find the maximum occurrence value in the dictionary
    max_count = max(count_dict.values()) if count_dict else 0

    # Filter out letters that have occurrences equal to the maximum and return them as a list of tuples
    result = [(char, count) for char, count in count_dict.items() if count == max_count]

    return dict(result)
```

