def is_prime(n):
    """Check whether an integer n is a prime or not."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def get_prime_factors(num):
    """Return a list of prime factors of the given number."""
    prime_factors = []

    # Divide num by two until it's odd. This handles even numbers efficiently since they are not primes (except 2).
    while num % 2 == 0:
        prime_factors.append(2)
        num //= 2

    for i in range(3, int(num**0.5) + 1, 2): # Check only odd factors starting from 3 up to sqrt of the number
        while num % i == 0:
            prime_factors.append(i)
            num //= i

    if num > 2:
        prime_factors.append(num)

    return prime_factors

def is_multiply_prime(a):
    """Return True if the given number a (less than 100) can be expressed as product of exactly three primes, False otherwise."""
    # Check that 'a' is less than 100. If not, return False immediately to save computation time for invalid inputs.
    if a >= 100:
        return False

    prime_factors = get_prime_factors(a)

    # Count the number of unique primes in 'prime_factors'. If there are exactly three, then it's true; otherwise false.
    if len(set(prime_factors)) == 3:
        return True
    else:
        return False

# Example usage:
print(is_multiply_prime(30)) # Should print True because 30 = 2 * 3 * 5, which are three prime numbers.
```
This script defines a helper function `is_prime` to check if an individual number is prime and another one called `get_prime_factors` that returns all the unique prime factors of any given integer less than or equal to 100 (since we're only interested in such numbers). The main function, `is_multiply_prime`, uses these helper functions to determine if a number is indeed composed by exactly three primes.

